--
-- Database: `medipus`
--

DELIMITER $$
--
-- Prosedur
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CekStokObat` ()   BEGIN
    DECLARE v_done INT DEFAULT FALSE;
    DECLARE v_stok INT;
    DECLARE v_kritis INT DEFAULT 0;
    DECLARE v_aman INT DEFAULT 0;

    -- Cursor untuk mengambil nilai Stok dari tabel obats
    DECLARE cur_stok CURSOR FOR 
        SELECT Stok FROM obats;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;

    OPEN cur_stok;

    read_loop: LOOP
        FETCH cur_stok INTO v_stok;
        IF v_done THEN
            LEAVE read_loop;
        END IF;

        IF v_stok < 50 THEN
            SET v_kritis = v_kritis + 1;
        ELSE
            SET v_aman = v_aman + 1;
        END IF;
    END LOOP;

    CLOSE cur_stok;

    SELECT 
        v_kritis AS Total_Obat_Kritis, 
        v_aman AS Total_Obat_Aman;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_HitungTotalLayananPoli` (IN `p_KodePoli` VARCHAR(10), OUT `p_StatusPendapatan` VARCHAR(50))   BEGIN
    DECLARE v_TotalBiaya DECIMAL(10,2) DEFAULT 0.00;

    SELECT COALESCE(SUM(t.Total_Biaya), 0) INTO v_TotalBiaya
    FROM transaksis t
    JOIN pemeriksaans p ON t.Id_Pemeriksaan = p.Id_Pemeriksaan
    JOIN registers r ON p.Id_Register = r.Id_Register
    WHERE r.Kode_Poli = p_KodePoli;

    CASE 
        WHEN v_TotalBiaya = 0 THEN
            SET p_StatusPendapatan = 'Belum Ada Pendapatan';
        WHEN v_TotalBiaya > 0 AND v_TotalBiaya <= 50000 THEN
            SET p_StatusPendapatan = 'Pendapatan Rendah';
        WHEN v_TotalBiaya > 50000 AND v_TotalBiaya <= 150000 THEN
            SET p_StatusPendapatan = 'Pendapatan Sedang';
        ELSE
            SET p_StatusPendapatan = 'Pendapatan Tinggi';
    END CASE;

    SELECT p_KodePoli AS Kode_Poli, v_TotalBiaya AS Total_Pendapatan, p_StatusPendapatan AS Status_Pendapatan;
END$$

--
-- Fungsi
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_HitungPPN` () RETURNS DECIMAL(10,2) DETERMINISTIC BEGIN
    RETURN 0.11;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_HitungSubtotalObat` (`p_Harga` DECIMAL(10,2), `p_Jumlah` INT) RETURNS DECIMAL(10,2) DETERMINISTIC BEGIN
    DECLARE v_Subtotal DECIMAL(10,2);
    SET v_Subtotal = p_Harga * p_Jumlah;
    RETURN v_Subtotal;
END$$

DELIMITER ;

