-- Trigger `detail_reseps`
--
DELIMITER $$
CREATE TRIGGER `trg_UpdateStokObat` AFTER INSERT ON `detail_reseps` FOR EACH ROW BEGIN
    UPDATE obats 
    SET Stok = Stok - NEW.Jumlah 
    WHERE Kode_Obat = NEW.Kode_Obat;
END
$$
