--
-- Trigger `obats`
--
DELIMITER $$
CREATE TRIGGER `trg_LogHargaObat` AFTER UPDATE ON `obats` FOR EACH ROW BEGIN
    IF OLD.Harga_satuan <> NEW.Harga_satuan THEN
        INSERT INTO log_perubahan_harga (Kode_Obat, Harga_Lama, Harga_Baru, Waktu_Ubah)
        VALUES (NEW.Kode_Obat, OLD.Harga_satuan, NEW.Harga_satuan, NOW());
    END IF;
END
$$
DELIMITER ;

